import"./chunk-ZW5NV4UO.js";var e={en:{title:"Bicycling on Mastodon: rides, touring and community",description:"Find cycling stories, practical bike advice and community rides on Mastodon. Choose people and hashtags, preview their posts and build your feed.",heading:"Bicycling on Mastodon",listTitle:"Bicycling",intro:["A weekend tour, a gravel ride or the school run by cargo bike: these riders and cycling groups share routes, equipment experiences and everyday adventures on two wheels.","Choose accounts and hashtags, then preview their posts. The selection includes recreational riding, practical bicycle care and constructive conversations about making cycling easier. Open hashtags can also contain unrelated posts."],faq:[{q:"Do I need an account?",a:"You can browse the selection and public posts without an account. Sign in with your Mastodon account to follow people and hashtags or make a list."},{q:"Is this only for competitive cyclists?",a:"No. Commuting, family rides, touring, mountain biking and everyday bicycle care belong here too. Some hashtags are quiet, and people may discuss other interests. Preview the feed and keep what suits you."},{q:"How do I get onto this list?",a:"Opted-in community accounts can qualify at any follower count when they pass the privacy checks and regularly share useful bicycling content. Sales-only feeds and automated ride logs without commentary are excluded. For questions or removal, contact @mawkingbird@mastodon.social."}]},de:{title:"Radfahren auf Mastodon: Radtouren, Alltag und Gemeinschaft",description:"Entdecke Radtouren, Alltag auf dem Fahrrad und praktische Erfahrungen auf Mastodon. W\xE4hle deutschsprachige Konten und passende Hashtags f\xFCr deinen Feed.",heading:"Radfahren auf Mastodon",listTitle:"Radfahren",intro:["Mit dem Faltrad durch die Stadt, auf Tour durchs Land oder mit dem Lastenrad zum Einkaufen: Hier teilen Radfahrende und Fahrradvereine ihre Erfahrungen, Strecken und Ideen.","W\xE4hle Konten und Hashtags und schau dir den Feed an. Neben Touren und Fahrradtechnik findest du praktische Angebote und konstruktive Gespr\xE4che \xFCber bessere Radwege. Hashtags sind offene Gespr\xE4chsr\xE4ume; manche sind ruhig oder enthalten auch andere Themen."],faq:[{q:"Brauche ich ein Konto?",a:"Du kannst die Auswahl und \xF6ffentliche Beitr\xE4ge ohne Konto ansehen. Melde dich mit deinem Mastodon-Konto an, um Konten und Hashtags zu folgen oder eine Liste anzulegen."},{q:"Geht es nur um Rennrad und Wettk\xE4mpfe?",a:"Nein. Alltagswege, Touren, Faltr\xE4der, Familienfahrten und Fahrradpflege geh\xF6ren genauso dazu. Die Konten k\xF6nnen auch andere Interessen teilen. Pr\xFCfe den Feed in der Vorschau und w\xE4hle aus, was dich anspricht."},{q:"Wie komme ich auf diese Liste?",a:"Auch kleine Community-Konten k\xF6nnen dabei sein, wenn sie der Auffindbarkeit zustimmen, die Datenschutzpr\xFCfung bestehen und regelm\xE4\xDFig interessante Fahrradbeitr\xE4ge teilen. Reine Verkaufsfeeds und automatische Trainingsprotokolle ohne eigene Einordnung geh\xF6ren nicht dazu. Bei Fragen oder f\xFCr eine Entfernung erreichst du @mawkingbird@mastodon.social."}]},fr:{title:"Le v\xE9lo sur Mastodon\xA0: sorties, ateliers et communaut\xE9",description:"D\xE9couvre le v\xE9lo au quotidien sur Mastodon\xA0: sorties, ateliers de r\xE9paration et voyages. Choisis des comptes francophones et des hashtags pour ton fil.",heading:"Le v\xE9lo sur Mastodon",listTitle:"V\xE9lo",intro:["Partir en balade, r\xE9parer son v\xE9lo ou trouver un atelier pr\xE8s de chez soi\xA0: cette s\xE9lection r\xE9unit des cyclistes et des associations qui partagent leurs exp\xE9riences et font vivre le v\xE9lo au quotidien.","Choisis des comptes et des hashtags, puis consulte un aper\xE7u du fil. Tu y trouveras aussi des initiatives concr\xE8tes pour faciliter les d\xE9placements \xE0 v\xE9lo. Les hashtags sont ouverts\xA0: certains sont peu actifs et peuvent accueillir des publications sans rapport avec le sujet."],faq:[{q:"Faut-il un compte\u202F?",a:"Tu peux parcourir la s\xE9lection et lire les publications publiques sans compte. Connecte-toi avec ton compte Mastodon pour suivre des personnes et des hashtags ou cr\xE9er une liste."},{q:"Est-ce r\xE9serv\xE9 aux cyclistes sportifs\u202F?",a:"Non. Les trajets du quotidien, les balades en famille, le voyage \xE0 v\xE9lo et la r\xE9paration ont toute leur place. Cette s\xE9lection comprend plusieurs associations locales. Consulte leurs publications pour trouver celles qui te correspondent."},{q:"Comment figurer dans cette liste\u202F?",a:"Les comptes qui acceptent d\u2019\xEAtre d\xE9couverts peuvent \xEAtre retenus quel que soit leur nombre d\u2019abonn\xE9s, apr\xE8s v\xE9rification des pr\xE9f\xE9rences de confidentialit\xE9 et de leurs publications sur le v\xE9lo. Les flux purement commerciaux et les relev\xE9s automatiques sans commentaire sont exclus. Pour une question ou un retrait, contacte @mawkingbird@mastodon.social."}]}};export{e as COPY};
